<script setup lang="ts">
import {ArrowLeft, ExternalLink, Images, Landmark, Move3D, X} from 'lucide-vue-next'
import {galleryArtworks,galleryRooms,type GalleryArtwork} from '~/data/art/gallery'
import {artistPortraits} from '~/data/art/artistPortraits'

const requestFetch=useRequestFetch()
const {data:cmsPage}=await useAsyncData('art-gallery-cms',async()=>{
  try{return await requestFetch<{items:GalleryArtwork[];total:number}>('/api/art/gallery',{query:{offset:0,limit:24}})}
  catch{return {items:[],total:0}}
})
const cmsArtworks=ref<GalleryArtwork[]>(cmsPage.value?.items||[])
const cmsTotal=ref(cmsPage.value?.total||0)
const loadingMore=ref(false)
const allArtworks=computed(()=>[...galleryArtworks,...cmsArtworks.value])
const rooms=computed(()=>[...galleryRooms,...Array.from({length:Math.ceil(cmsArtworks.value.length/6)},(_,i)=>({id:i+6,name:`Պատկերասրահի նոր սրահ ${i+1}`,era:'ՆՈՐ ՍՐԱՀ',summary:'CMS-ից հրապարակված գործեր',direction:'արևելք'}))])

const gallery=ref<{visit:(index:number)=>void;reset:()=>void;focusArtwork:(id:string)=>void}>()
const frame=ref<HTMLElement>()
const selected=ref<GalleryArtwork|null>(null)
const closeButton=ref<HTMLButtonElement>()
let previousFocus:HTMLElement|null=null
const room=ref(0)
const ready=ref(false)
const filter=ref<number|null>(null)
const artistGroups=computed(()=>Array.from(allArtworks.value.filter(item=>!['buddha-shakyamuni','buddha-indra-brahma','thinker','venus-de-milo'].includes(item.id)).reduce((groups,item)=>{
  const works=groups.get(item.creator)||[]
  works.push(item)
  groups.set(item.creator,works)
  return groups
},new Map<string,GalleryArtwork[]>())).sort((a,b)=>b[1].length-a[1].length))
function portraitFor(creator:string,works:GalleryArtwork[]){return artistPortraits[creator]?.image||works.find(item=>item.creatorPortrait)?.creatorPortrait}
function roomName(index:number){return rooms.value[index]?.name||''}
async function loadMore(){
  if(loadingMore.value||cmsArtworks.value.length>=cmsTotal.value)return
  loadingMore.value=true
  try{
    const page=await $fetch<{items:GalleryArtwork[];total:number}>('/api/art/gallery',{query:{offset:cmsArtworks.value.length,limit:24}})
    cmsTotal.value=page.total
    ready.value=false
    cmsArtworks.value=[...cmsArtworks.value,...page.items]
  }finally{loadingMore.value=false}
}
function visit(index:number){gallery.value?.visit(index);filter.value=index===0?null:index;frame.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
function jumpToArtwork(item:GalleryArtwork){gallery.value?.focusArtwork(item.id);filter.value=item.room;frame.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
function open(item:GalleryArtwork){previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;selected.value=item.id==='thinker'&&cmsArtworks.value.length?{...item,room:rooms.value.length-1}:item;nextTick(()=>closeButton.value?.focus())}
function select(id:string){const item=allArtworks.value.find(item=>item.id===id);if(item)open(item)}
function close(){selected.value=null;nextTick(()=>previousFocus?.focus({preventScroll:true}))}
onMounted(()=>window.addEventListener('keydown',escape))
onUnmounted(()=>window.removeEventListener('keydown',escape))
function escape(event:KeyboardEvent){if(event.key==='Escape')close()}
useHead({title:'Արվեստի վիրտուալ պատկերասրահ — COGNITIO',meta:[{name:'description',content:'Շրջիր COGNITIO-ի եռաչափ արվեստի սրահներում և բացահայտիր նշանավոր քանդակներ, նկարներ ու փորագրություններ։'}]})
</script>

<template>
  <main class="art-page">
    <div class="art-breadcrumb"><NuxtLink to="/"><ArrowLeft :size="17"/> Գլխավոր</NuxtLink><span>COGNITIO · ԱՐՎԵՍՏ</span></div>
    <header class="art-hero">
      <div><p class="eyebrow">ՎԻՐՏՈՒԱԼ ՊԱՏԿԵՐԱՍՐԱՀ</p><h1>Արվեստի <em>սրահներ</em></h1><p>Մտիր բարձր առաստաղով կենտրոնական դահլիճ, անցիր չորս ուղղությամբ բաց սրահներ և բացահայտիր մեծածավալ գեղանկարներ ու քանդակներ։</p></div>
      <div class="hero-mark" aria-hidden="true"><Images :size="43" :stroke-width="1"/><span>COGNITIO</span></div>
    </header>
    <section ref="frame" class="art-frame" aria-label="Եռաչափ արվեստի պատկերասրահ">
      <ClientOnly><LazyArtVirtualGallery :key="cmsArtworks.length" ref="gallery" :cms-artworks="cmsArtworks" @ready="ready=true" @room="room=$event" @select="select"/><template #fallback><div class="art-placeholder">Բացվում են արվեստի սրահները…</div></template></ClientOnly>
    </section>
    <div class="art-frame-caption"><span><Move3D :size="17"/> Կրկնակի սեղմիր հատակին՝ քայլելու համար․ անցումները միշտ բաց են</span><span>Ընթացիկ սրահ՝ {{roomName(room)}}</span></div>
    <nav class="art-room-nav" aria-label="Ընտրել սրահ">
      <button type="button" :class="{active:filter===null}" :aria-pressed="filter===null" @click="filter=null;gallery?.reset()"><Landmark :size="19"/><span>Բոլոր գործերը</span></button>
      <button v-for="item in rooms.slice(1)" :key="item.id" type="button" :class="{active:filter===item.id}" :aria-pressed="filter===item.id" :disabled="!ready" @click="visit(item.id)"><small>{{item.era}}</small><span>{{item.name}}</span></button>
    </nav>
    <button v-if="cmsArtworks.length<cmsTotal" type="button" class="art-load-rooms" :disabled="loadingMore" @click="loadMore">{{loadingMore?'Բեռնվում են…':`Բացել հաջորդ սրահները (${cmsTotal-cmsArtworks.length} գործ)`}}</button>
    <section class="artist-section" aria-label="Նկարիչների գործերը">
      <div class="collection-heading"><div><p class="eyebrow">ՆԿԱՐԻՉՆԵՐ ԵՎ ԳՈՐԾԵՐ</p><h2>Ընտրիր հեղինակին, մտիր սրահ</h2></div><p>Սեղմիր գործի անունը՝ 3D սրահում նրա դիմաց կանգնելու համար</p></div>
      <div class="artist-grid"><article v-for="[creator,works] in artistGroups" :key="creator" class="artist-card"><div class="artist-preview"><img v-if="portraitFor(creator,works)" :src="portraitFor(creator,works)" :alt="`${creator}՝ դիմանկար`" width="115" height="105" loading="lazy" decoding="async"/><div><small>{{works.length}} գործ</small><h3>{{creator}}</h3><a v-if="artistPortraits[creator]||works.find(work=>work.creatorPortraitSource)" :href="artistPortraits[creator]?.source||works.find(work=>work.creatorPortraitSource)?.creatorPortraitSource" :title="artistPortraits[creator]?.credit||works.find(work=>work.creatorPortraitCredit)?.creatorPortraitCredit" target="_blank" rel="noopener noreferrer" class="artist-credit">Դիմանկարի աղբյուր ↗</a><p v-if="works.find(work=>work.creatorInfo)?.creatorInfo" class="artist-bio">{{works.find(work=>work.creatorInfo)?.creatorInfo}}</p></div></div><div class="artist-works"><button v-for="work in works" :key="work.id" type="button" :disabled="!ready" @click="jumpToArtwork(work)"><span>{{work.title}}</span><small>{{work.date}} ↗</small></button></div></article></div>
    </section>
      <div v-if="selected" class="art-modal-backdrop" @click.self="close"><section class="art-detail" role="dialog" aria-modal="true" :aria-label="selected.title"><button ref="closeButton" type="button" class="art-detail-close" aria-label="Փակել" @click="close"><div aria-hidden="true"><X :size="20"/></div></button><div class="art-detail-image"><img :src="selected.image" :alt="selected.originalTitle" width="600" height="500"/><p>{{selected.imageCredit}}</p></div><div class="art-detail-copy"><p class="eyebrow">{{roomName(selected.room)}} · {{selected.medium}}</p><h2>{{selected.title}}</h2><p class="original-title">{{selected.originalTitle}}</p><dl><div><dt>Հեղինակ</dt><dd>{{selected.creator}}</dd></div><div><dt>Թվագրում</dt><dd>{{selected.date}}</dd></div><div v-if="selected.location"><dt>Գտնվելու վայր</dt><dd>{{selected.location}}</dd></div><div v-if="selected.dimensions"><dt>Չափեր</dt><dd>{{selected.dimensions}}</dd></div></dl><h3>Գործի մասին</h3><p class="art-description">{{selected.description}}</p><p v-if="selected.context" class="art-description">{{selected.context}}</p><div v-if="selected.lookFor" class="art-look"><strong>Ինչ նկատել սրահում</strong><p>{{selected.lookFor}}</p></div><a :href="selected.source" target="_blank" rel="noopener noreferrer"><ExternalLink :size="16"/> Թանգարանի կամ արխիվի գրառումը</a><p class="image-credit">Պատկեր՝ <a :href="selected.imageSource" target="_blank" rel="noopener noreferrer">աղբյուր</a><template v-if="selected.imageLicense"> · <a :href="selected.imageLicense" target="_blank" rel="noopener noreferrer">արտոնագիր</a></template></p><p v-if="selected.modelSource" class="image-credit">3D մոդել՝ {{selected.modelCredit}} · <a :href="selected.modelSource" target="_blank" rel="noopener noreferrer">աղբյուր</a></p></div></section></div>
  </main>
</template>

