bec8;font-size:14px}.art-detail dl{display:grid;gap:12px;margin:26px 0;padding:18px 0;border-top:1px solid #ffffff26;border-bottom:1px solid #ffffff26}.art-detail dl div{display:grid;grid-template-columns:90px 1fr;gap:10px;font-size:15px}.art-detail dt{color:#bb9d6d}.art-detail dd{color:#f0e5d2}.art-description{font-size:16px;line-height:1.8;color:#d6dee1}.art-detail-copy>a{display:inline-flex;align-items:center;gap:7px;margin-top:22px;color:#edce8e;font-size:14px;text-decoration:underline}.image-credit{margin-top:26px;font-size:12px;line-height:1.6;color:#9dabb4}.image-credit a{text-decoration:underline}.art-detail-close{position:absolute;right:15px;top:15px;display:grid;place-items:center;width:37px;height:37px;border:1px solid #ffffff73;border-radius:50%;background:#0b1728e0;color:white}
